    ("wp49_eol_policy_index_blobs.py", "# -*- coding: utf-8 -*-\n\"\"\"F2-A (ADR-0018) — regression EOL canonical chạy TRONG canonical selftest.\n\nPHÂN CÔNG CÓ CHỦ ĐÍCH giữa hai suite, không phải trùng lặp lười:\n\n- Fragment NÀY chạy trong `tl --selftest` ở CẢ cây dev lẫn gói đã giải nén. Writer canonical,\n  `.gitattributes` và các bảng extension runtime đều có trong cả hai topology; `.editorconfig`\n  là config dev-side nên CỐ Ý bị release loại. Fragment phân biệt topology bằng chính source\n  fragment/bundled adapter, vì vậy bundle không biến thành ca rỗng chỉ vì thiếu config dev-side.\n- Nó KHÔNG import `.githooks/eol_policy.py` — `.githooks/` bị `_RELEASE_EXCLUDE_DIRS` loại khỏi\n  gói. `.githooks/eol_policy_test.py` dựng bundle thật, giải nén và chạy chính case `wp49` từ\n  generated adapter để khoá đường package này.\n- `.githooks/eol_policy_test.py` giữ phần hành vi validator ở tầng git (rename/copy, tên Unicode,\n  binary, tệp mới). Nó cần một kho git thật nên không package-safe; CI gọi nó CHẶN trên cả\n  ubuntu lẫn windows.\n\nVì sao cần ca trong canonical selftest: `.gitattributes` một mình KHÔNG chặn được artifact phái\nsinh. Tệp phái sinh được GHI RA trước, git chỉ nhìn thấy nó sau. Nếu writer nhả CRLF thì mỗi lần\ntái sinh golden/manifest lại đẻ một đợt renormalize, và F2 sẽ tự mở lại chính lớp hỏng nó vừa đóng.\n\"\"\"\nfrom __future__ import annotations\n\nimport re\nimport tempfile\nfrom pathlib import Path\n\nTEST_ID = \"wp49_eol_policy_index_blobs\"\n\n# Sàn chống RỖNG. Không phải bản sao của danh sách: nếu một nguồn hợp đồng bị đổi tên hay import\n# hỏng, tập suy ra co lại và phép `⊆` sẽ ĐÚNG một cách vô nghĩa. Sàn này biến \"vô tình rỗng\" thành\n# ĐỎ. Đo 07-08-2026: hợp nhất ba nguồn cho 12 họ.\n_SAN_TOI_THIEU = 10\n\n\ndef _root(tl_module):\n    \"\"\"Gốc kho/gói: `tl.py` luôn nằm ở `<root>/scripts/`, đúng ở cả cây dev lẫn bản giải nén.\"\"\"\n    return Path(tl_module.__file__).resolve().parent.parent\n\n\ndef _topology(tl_module):\n    \"\"\"Nhận diện tường minh dev/bundle; trạng thái lai hoặc thiếu adapter phải fail closed.\"\"\"\n    root = _root(tl_module)\n    source = root / \"scripts\" / \"test_fragments\" / \"wp49_eol_policy_index_blobs.py\"\n    bundled = root / \"scripts\" / \"tl_test_fragments_bundled.py\"\n    editorconfig = root / \".editorconfig\"\n    if source.is_file() and bundled.is_file() and editorconfig.is_file():\n        return \"dev\"\n    if not source.exists() and bundled.is_file() and not editorconfig.exists():\n        return \"bundle\"\n    return None\n\n\ndef _writer_canonical(tl_module):\n    \"\"\"Writer phải nhả LF dù đầu vào là CRLF, CR đơn lẻ hay trộn lẫn.\n\n    `newline=\"\\\\n\"` một mình KHÔNG đủ: nó tắt phép dịch `\\\\n`→`\\\\r\\\\n` lúc ghi nhưng không đụng\n    `\\\\r` đã nằm sẵn trong chuỗi. Đọc một tệp CRLF rồi ghi lại qua writer \"đã ghim LF\" vẫn ra CRLF.\n    \"\"\"\n    write = getattr(tl_module, \"_write_text_atomic\", None)\n    if not callable(write):\n        return False\n    mau = [\n        \"a\\r\\nb\\r\\n\",          # CRLF toàn phần\n        \"a\\r\\nb\\nc\\r\\n\",       # trộn\n        \"a\\rb\\r\",              # CR đơn lẻ (Mac cổ / stdout lạ)\n        \"a\\nb\\n\",              # vốn đã LF: phải giữ nguyên, không nhân đôi\n    ]\n    with tempfile.TemporaryDirectory(prefix=\"wp49_writer_\") as tmp:\n        for i, text in enumerate(mau):\n            # Ghi vào thư mục con CHƯA tồn tại: khoá luôn hợp đồng mkdir của writer.\n            dest = Path(tmp) / (\"sub%d\" % i) / \"out.txt\"\n            write(dest, text)\n            raw = dest.read_bytes()\n            if b\"\\r\" in raw:\n                return False\n            if raw.decode(\"utf-8\") != text.replace(\"\\r\\n\", \"\\n\").replace(\"\\r\", \"\\n\"):\n                return False\n    return True\n\n\ndef _writer_van_nguyen_tu(tl_module):\n    \"\"\"Chuẩn hoá không được làm mất ngữ nghĩa nguyên tử: ghi đè xong không để lại tmp lảng vảng.\"\"\"\n    write = tl_module._write_text_atomic\n    with tempfile.TemporaryDirectory(prefix=\"wp49_atomic_\") as tmp:\n        dest = Path(tmp) / \"out.txt\"\n        write(dest, \"cu\\r\\n\")\n        write(dest, \"moi\\r\\n\")\n        if dest.read_bytes() != b\"moi\\n\":\n            return False\n        # `mkstemp` cùng thư mục + `os.replace` ⇒ sau khi xong chỉ còn ĐÚNG tệp đích.\n        return sorted(p.name for p in Path(tmp).iterdir()) == [\"out.txt\"]\n\n\ndef _ho_binary_suy_ra(tl_module):\n    \"\"\"SUY RA họ binary từ bảng extension ingest/loader của kho, KHÔNG chép tay.\n\n    Một danh sách chép tay có khuyết điểm đi thẳng vào cả policy lẫn test, rồi hai bên gật đầu\n    với nhau — đúng cái bẫy đã để lọt `.xls/.odt/.tif/.tiff` ở vòng trước. Neo vào hợp đồng thật:\n\n      PROFILE_INGEST_ALLOWED_EXTS  tl.py                     allowlist của `profile-ingest`\n      INGEST_LOCAL_EXTS            tl_core/ingest_contract   allowlist của `ingest-local`\n      OCR_SOURCE_EXTS              tl_core/ingest_contract   nguồn đi đường OCR (ảnh + PDF)\n      _MIME_BY_EXT                 tl.py                     để loại `text/*` khỏi hợp nhất\n\n    Mở thêm một đuôi ở bất kỳ allowlist nào mà quên khai `-text` ⇒ ca này ĐỎ.\n    \"\"\"\n    from tl_core.ingest_contract import INGEST_LOCAL_EXTS, OCR_SOURCE_EXTS\n    nguon = [set(tl_module.PROFILE_INGEST_ALLOWED_EXTS), set(INGEST_LOCAL_EXTS), set(OCR_SOURCE_EXTS)]\n    if not all(nguon):                      # nguồn rỗng ⇒ phép ⊆ sẽ đúng vô nghĩa\n        return None\n    mime = getattr(tl_module, \"_MIME_BY_EXT\", None)\n    if not mime:\n        return None\n    hop = set().union(*nguon)\n    return {e for e in hop if not str(mime.get(e, \"\")).startswith(\"text/\")}\n\n\ndef _policy_khai_du(tl_module):\n    \"\"\"`.gitattributes` phải khai ĐỦ policy ADR-0018 và ĐỦ mọi họ binary suy ra được.\"\"\"\n    path = _root(tl_module) / \".gitattributes\"\n    if not path.is_file():\n        return False\n    noi_dung = path.read_text(encoding=\"utf-8\")\n    dong = [d.strip() for d in noi_dung.splitlines()]\n    dong = [d for d in dong if d and not d.startswith(\"#\")]\n    can = [\n        \"* text=auto eol=lf\",\n        \"*.cmd text eol=crlf\",\n        \"*.bat text eol=crlf\",\n        \"references/golden/** -text\",\n    ]\n    if any(c not in dong for c in can):\n        return False\n    # `* -text` cũ phải BIẾN MẤT: còn nó thì policy mới vô hiệu ngay từ dòng đầu.\n    if \"* -text\" in dong:\n        return False\n\n    suy_ra = _ho_binary_suy_ra(tl_module)\n    if not suy_ra or len(suy_ra) < _SAN_TOI_THIEU:\n        return False\n    khai = {m.group(1) for m in re.finditer(r\"(?m)^\\*(\\.[A-Za-z0-9]+) -text\\s*$\", noi_dung)}\n    return suy_ra <= khai\n\n\ndef _editorconfig_dong_bo(tl_module):\n    \"\"\"Ở topology dev, `.editorconfig` phải phủ những họ mà `.gitattributes` khai `-text`.\n\n    Hai tệp cưỡng chế cùng một policy ở hai tầng khác nhau (git vs editor). Chúng SẼ trôi lệch,\n    và bên quên cập nhật chính là bên để editor ghi lại CRLF vào một tệp đáng ra bất khả xâm phạm.\n    Gói release không ship config editor; `_topology()` xác nhận sự vắng mặt đó là cấu trúc bundle\n    thật, không phải một tệp dev vô tình mất rồi bị bỏ qua.\n    \"\"\"\n    root = _root(tl_module)\n    ec = root / \".editorconfig\"\n    if not ec.is_file():\n        return False\n    suy_ra = _ho_binary_suy_ra(tl_module)\n    if not suy_ra or len(suy_ra) < _SAN_TOI_THIEU:\n        return False\n    phu = set()\n    for m in re.finditer(r\"(?m)^\\[\\*\\.\\{([^}]*)\\}\\]\\s*$\", ec.read_text(encoding=\"utf-8\")):\n        phu |= {\".\" + x.strip() for x in m.group(1).split(\",\") if x.strip()}\n    return suy_ra <= phu\n\n\ndef run(tl_module):\n    topology = _topology(tl_module)\n    return bool(\n        topology\n        and _writer_canonical(tl_module)\n        and _writer_van_nguyen_tu(tl_module)\n        and _policy_khai_du(tl_module)\n        and (topology == \"bundle\" or _editorconfig_dong_bo(tl_module))\n    )\n"),
    ("wp726_script_nlm_canary.py", "# -*- coding: utf-8 -*-\n\"\"\"wp726 — ba script shell NLM phán sống/chết bằng canary, không bằng `nlm login --check`, không nuốt mã thoát.\n\nChạy BẢN THẬT của `nlm-auto-refresh.sh`, `env-reimport.sh`, `nlm-auth-import.sh` bằng `bash` với `TL_ROOT` trỏ\nmột gốc giả: `scripts/tl.py` giả (vừa là module cho probe canary, vừa là CLI), `nlm`/`gws` giả trên PATH. Đồ giả\nGIỮ TRẠNG THÁI qua một tệp JSON — `nlm login --check` LUÔN báo \"valid\" (false-green), còn canary và mã của\n`nlm-auth-stage` là hai biến độc lập — và ghi nhật ký mọi lời gọi. Mọi đồ giả in một chuỗi canh; đầu ra của\nscript không được chứa nó.\n\"\"\"\n\nimport importlib.util\nimport json\nimport os\nfrom pathlib import Path\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\n\n\nTEST_ID = \"wp726_script_nlm_canary\"\n\n_CANH = \"SENTINEL-COOKIE-wp726\"\n\n_TL_GIA = r'''\nimport json, os, sys\n_ST = os.environ[\"WP726_STATE\"]\n_LOG = os.environ[\"WP726_LOG\"]\nNLM_CRED_FILEID = \"FAKE-NLM-CRED\"\n\ndef _ghi(dong):\n    with open(_LOG, \"a\", encoding=\"utf-8\") as f:\n        f.write(dong + \"\\n\")\n\ndef _trang_thai():\n    with open(_ST, encoding=\"utf-8\") as f:\n        return json.load(f)\n\ndef _imp(name):\n    return sys.modules[__name__]\n\ndef bind(_m):\n    return None\n\ndef _nlm_canary_notebook(nb):\n    return \"NB-OFFLINE\"\n\ndef _nlm_auth_alive(nb, require_notebook_body=False):\n    _ghi(\"canary require_body=%s\" % require_notebook_body)\n    print(\"%s canary\" % os.environ.get(\"WP726_CANH\", \"\"))\n    if not require_notebook_body:\n        return True, \"rc0-only\"          # probe lỏng = false-green: chỉ phép đo đòi THÂN mới thấy canary thật\n    return _trang_thai()[\"canary\"], \"OFFLINE\"\n\nif __name__ == \"__main__\":\n    lenh = sys.argv[1] if len(sys.argv) > 1 else \"\"\n    _ghi(\"tl \" + \" \".join(sys.argv[1:]))\n    print(\"%s tl %s\" % (os.environ.get(\"WP726_CANH\", \"\"), lenh))\n    print(\"%s\" % os.environ.get(\"WP726_CANH\", \"\"), file=sys.stderr)\n    if lenh == \"ping\":\n        print('{\"ok\": true, \"version\": \"offline\"}')\n    elif lenh == \"nlm-auth-stage\":\n        sys.exit(_trang_thai()[\"stage_rc\"])\n    elif lenh == \"nlm-auth-load\":\n        sys.exit(_trang_thai().get(\"load_rc\", 0))\n    sys.exit(0)\n'''\n\n_CONVERT_GIA = r'''\nimport pathlib, sys\npathlib.Path(sys.argv[2]).mkdir(parents=True, exist_ok=True)\n(pathlib.Path(sys.argv[2]) / \"cookies.json\").write_text(\"[]\", encoding=\"utf-8\")\n'''\n\n_NLM_GIA = '''#!/usr/bin/env bash\necho \"nlm $*\" >> \"$WP726_LOG\"\necho \"$WP726_CANH\"\ncase \"$1 $2\" in\n  \"login --check\") echo \"Authentication valid. Notebooks found: 7\"; exit 0 ;;\nesac\nexit 0\n'''\n\n_GWS_GIA = r'''\nimport json, os, sys\na = sys.argv[1:]\nwith open(os.environ[\"WP726_LOG\"], \"a\", encoding=\"utf-8\") as f:\n    f.write(\"gws \" + \" \".join(a) + \"\\n\")\nwith open(os.environ[\"WP726_STATE\"], encoding=\"utf-8\") as f:\n    st = json.load(f)\nlenh = \" \".join(a[:3])\nif lenh == \"drive files list\":\n    tep = [{\"id\": \"EXPORT-1\", \"name\": \"nlm-auth-x.json\", \"modifiedTime\": \"2026-10-01T00:00:00Z\"}] if st.get(\"export\") else []\n    print(json.dumps({\"files\": tep}))\nelif lenh == \"drive files get\":\n    if \"--output\" in a:\n        with open(a[a.index(\"--output\") + 1], \"w\", encoding=\"utf-8\") as f:\n            f.write('[{\"name\": \"SID\", \"value\": \"x\", \"domain\": \".google.com\"}]')\n    else:\n        print(\"{}\")\n'''\n\n\ndef _dung_goc(tam, kho):\n    goc = tam / \"goc\"\n    (goc / \"scripts\").mkdir(parents=True)\n    (goc / \"scripts\" / \"tl.py\").write_text(_TL_GIA, encoding=\"utf-8\")\n    (goc / \"scripts\" / \"nlm_auth_convert.py\").write_text(_CONVERT_GIA, encoding=\"utf-8\")\n    bin_ = tam / \"bin\"\n    bin_.mkdir()\n    for ten, noi_dung in ((\"nlm\", _NLM_GIA), (\"gws\", \"#!\" + sys.executable + \"\\n\" + _GWS_GIA)):\n        p = bin_ / ten\n        p.write_text(noi_dung, encoding=\"utf-8\")\n        p.chmod(0o755)\n    # `nlm-auto-refresh.sh` gọi `./scripts/nlm-auth-import.sh` TƯƠNG ĐỐI gốc ⇒ đặt BẢN THẬT vào gốc giả.\n    shutil.copy2(kho / \"scripts\" / \"nlm-auth-import.sh\", goc / \"scripts\" / \"nlm-auth-import.sh\")\n    (tam / \"home\").mkdir()\n    cookie = tam / \"cookie.json\"\n    cookie.write_text('[{\"name\": \"SID\", \"value\": \"x\", \"domain\": \".google.com\"}]', encoding=\"utf-8\")\n    return goc, bin_, cookie\n\n\ndef _chay(bash, kho, tam, goc, bin_, script, args, trang_thai):\n    st = tam / \"state.json\"\n    log = tam / \"calls.log\"\n    st.write_text(json.dumps(trang_thai), encoding=\"utf-8\")\n    log.write_text(\"\", encoding=\"utf-8\")\n    env = {\n        \"PATH\": f\"{bin_}{os.pathsep}{os.environ.get('PATH', '')}\",\n        \"HOME\": str(tam / \"home\"),\n        \"TL_ROOT\": str(goc),\n        \"TL_PYTHON\": sys.executable,\n        \"TL_TOKEN\": \"offline-test-token\",\n        \"WP726_STATE\": str(st),\n        \"WP726_LOG\": str(log),\n        \"WP726_CANH\": _CANH,\n        \"PYTHONDONTWRITEBYTECODE\": \"1\",\n    }\n    r = subprocess.run([bash, str(kho / \"scripts\" / script), *args], env=env, cwd=str(goc),\n                       capture_output=True, text=True, timeout=120)\n    return r.returncode, r.stdout + r.stderr, log.read_text(encoding=\"utf-8\").splitlines()\n\n\ndef _sach(out, calls):\n    \"\"\"Không lộ chuỗi canh, không có lời gọi `nlm login --check`.\"\"\"\n    return _CANH not in out and not any(c.startswith(\"nlm login --check\") for c in calls)\n\n\ndef _ca(bash, kho):\n    kq = {}\n    with tempfile.TemporaryDirectory(prefix=\"wp726_\") as td:\n        tam = Path(td)\n        goc, bin_, cookie = _dung_goc(tam, kho)\n\n        def chay(script, args, canary, stage_rc, **them):\n            return _chay(bash, kho, tam, goc, bin_, script, args, {\"canary\": canary, \"stage_rc\": stage_rc, **them})\n\n        # nlm-auto-refresh.sh — phán quyết = mã của nlm-auth-stage\n        for ten, stage_rc, ma in ((\"tu_dong_song\", 0, 0), (\"tu_dong_chet\", 4, 3), (\"tu_dong_ha_tang\", 5, 2)):\n            rc, out, calls = chay(\"nlm-auto-refresh.sh\", [], None, stage_rc)\n            n_stage = sum(1 for c in calls if c == \"tl nlm-auth-stage\")\n            kq[ten] = rc == ma and n_stage == 1 and _sach(out, calls)\n\n        # nlm-auto-refresh.sh — có export MỚI: import (canary + stage) rồi KHÔNG stage lần hai; chỉ xoá plaintext\n        # khi import+stage thành công (lượt review 1, F2)\n        for ten, canary, stage_rc, ma, can_stage, can_xoa in ((\"tu_dong_export_song\", True, 0, 0, 1, 1),\n                                                              (\"tu_dong_export_stage_loi\", True, 4, 3, 2, 0)):\n            rc, out, calls = chay(\"nlm-auto-refresh.sh\", [], canary, stage_rc, export=True)\n            n_stage = sum(1 for c in calls if c == \"tl nlm-auth-stage\")\n            n_xoa = sum(1 for c in calls if c.startswith(\"gws drive files delete\"))\n            kq[ten] = rc == ma and n_stage == can_stage and n_xoa == can_xoa and _sach(out, calls)\n\n        # env-reimport.sh — nlm-auth-load lỗi: chỉ báo mã, không in đầu ra lệnh (lượt review 1, F3)\n        rc, out, calls = chay(\"env-reimport.sh\", [], True, 0, load_rc=5)\n        kq[\"env_load_loi_khong_lo\"] = rc == 0 and \"nlm-auth-load lỗi (rc=5)\" in out and _sach(out, calls)\n\n        # env-reimport.sh — canary đòi thân đúng notebook\n        for ten, canary, ma in ((\"env_song\", True, 0), (\"env_chet\", False, 3), (\"env_khong_ro\", None, 4)):\n            rc, out, calls = chay(\"env-reimport.sh\", [], canary, 0)\n            kq[ten] = (rc == ma and \"canary require_body=True\" in calls\n                       and not any(c.startswith(\"tl nlm-auth-stage\") for c in calls) and _sach(out, calls))\n\n        # nlm-auth-import.sh — bước 4 canary, bước 5 phân biệt rc của stage\n        tham = [\"--file\", str(cookie)]\n        for ten, canary, stage_rc, ma, can_stage in (\n                (\"nhap_chet\", False, 0, 4, 0), (\"nhap_khong_ro\", None, 0, 6, 0), (\"nhap_song\", True, 0, 0, 1),\n                (\"nhap_stage_4\", True, 4, 5, 1), (\"nhap_stage_5\", True, 5, 5, 1)):\n            rc, out, calls = chay(\"nlm-auth-import.sh\", tham, canary, stage_rc)\n            n_stage = sum(1 for c in calls if c == \"tl nlm-auth-stage\")\n            kq[ten] = rc == ma and n_stage == can_stage and _sach(out, calls)\n            kq[ten + \"_out\"] = out\n    ok_4_5 = (\"canary của lệnh stage KHÔNG dương\" in kq.pop(\"nhap_stage_4_out\")\n              and \"lỗi stage\" in kq.pop(\"nhap_stage_5_out\"))\n    for k in [k for k in kq if k.endswith(\"_out\")]:\n        kq.pop(k)\n    kq[\"nhap_phan_biet_4_5\"] = ok_4_5\n    return kq\n\n\ndef _bash_nen(kho):\n    \"\"\"`ops/bash_nen.py` của kho (cổng cấm `bash` TRẦN — Issue #570). None khi cây không mang `ops/` (gói phát hành).\"\"\"\n    p = kho / \"ops\" / \"bash_nen.py\"\n    if not p.is_file():\n        return None\n    spec = importlib.util.spec_from_file_location(\"_wp726_bash_nen\", p)\n    mod = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(mod)\n    return mod\n\n\ndef run(tl_module):\n    kho = Path(tl_module.__file__).resolve().parent.parent\n    bash_nen = _bash_nen(kho)\n    if os.name != \"posix\" or bash_nen is None:\n        # Lệch có khai so với spec N6: API fragment chỉ có đúng/sai, không có trạng thái `skipped`. Nền không POSIX\n        # (Windows) và cây phát hành (không mang `ops/bash_nen.py`, bộ tìm bash DUY NHẤT được phép) không chạy ca\n        # này; ca trả True và in lý do — handoff khai riêng.\n        print(\"[wp726_script_nlm_canary] BỎ QUA (os.name=%s, ops/bash_nen.py %s)\"\n              % (os.name, \"có\" if bash_nen else \"vắng\"), file=sys.stderr)\n        return True\n    bash, _chan_doan = bash_nen.tim_bash()\n    if not bash:\n        return False                     # cây dev POSIX mà không có bash dùng được ⇒ ĐỎ, không tha\n    kq = _ca(bash, kho)\n    return bool(kq) and all(kq.values())\n"),
